import{_ as o,o as i,c as a,ag as l}from"./chunks/framework.DXGyWiRo.js";const c="/assets/ch00-dennis.CfT9oqqE.png",C=JSON.parse('{"title":"什么是C语言？","description":"","frontmatter":{},"headers":[],"relativePath":"langs/c/C语言概述.md","filePath":"langs/c/C语言概述.md","lastUpdated":1741365746000}'),d={name:"langs/c/C语言概述.md"};function t(r,e,n,s,h,p){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="什么是c语言" tabindex="-1">什么是C语言？ <a class="header-anchor" href="#什么是c语言" aria-label="Permalink to &quot;什么是C语言？&quot;">​</a></h1><h2 id="本章大纲" tabindex="-1">本章大纲 <a class="header-anchor" href="#本章大纲" aria-label="Permalink to &quot;本章大纲&quot;">​</a></h2><p>==程序==是什么？</p><ol><li><p>程序又叫软件，最常见的就是手机<code>APP</code>和电脑软件，不常见的有服务器软件、嵌入式软件、穿戴设备软件。</p></li><li><p>程序可以看作是数据和逻辑的组合</p></li><li><p>为了让计算机执行某些操作或解决某个问题而编写的一系列有序指令的集合</p></li></ol><p>C语言之父、UNIX之父——丹尼斯·里奇（<code>Dennis Ritchie</code>），<code>1941-2011</code></p><p><img src="'+c+'" alt="Dennis Ritchie"></p><p>C语言的诞生与UNIX操作系统密不可分。</p><p><code>ANSI</code>，<a href="https://www.ansi.org/" target="_blank" rel="noreferrer">American National Standards Institute</a>，美国国家标准学会</p><p><code>ISO</code>，<a href="https://www.iso.org/" target="_blank" rel="noreferrer">International Organization for Standardization</a>，国际化标准组织</p><h2 id="c语言发展历程" tabindex="-1">C语言发展历程 <a class="header-anchor" href="#c语言发展历程" aria-label="Permalink to &quot;C语言发展历程&quot;">​</a></h2><ol><li><code>1972.11</code> <code>C</code>语言诞生</li><li><code>1978.11</code> 贝尔实验室正式发布<code>C</code>语言</li><li><code>1983</code> <code>ANSI</code>开始制定<code>C</code>语言标准</li><li><code>1989.12</code> <code>ANSI</code>完成标准的制定</li><li><code>1990.9</code> <code>ANSI</code>被<code>ISO</code>采纳为国际标准</li><li><code>1999.8</code> <code>ISO</code>发布<code>C99</code>标准</li></ol><h2 id="c语言的特点" tabindex="-1">C语言的特点 <a class="header-anchor" href="#c语言的特点" aria-label="Permalink to &quot;C语言的特点&quot;">​</a></h2><ol><li>代码级别的跨平台</li><li>允许直接访问物理地址，对硬件进行操作。（操作系统、数据库、杀毒软件、防火墙、驱动程序、服务器程序）</li><li>面向过程</li><li>传参方式：按值传递、传递指针</li><li>没有对象</li><li>预编译处理，代码质量高，执行效率高</li></ol><h2 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h2><ul><li><code>Visual Studio Code &amp; Visual Studio Community</code></li><li><code>Code::Blocks</code></li><li><code>DEV C++</code></li><li><code>Visual C++2010 Express</code></li><li><code>JetBrains CLion</code></li><li><code>Source Insight 4</code></li><li><code>Eclipse</code></li></ul><h2 id="c程序运行机制简述" tabindex="-1">C程序运行机制简述 <a class="header-anchor" href="#c程序运行机制简述" aria-label="Permalink to &quot;C程序运行机制简述&quot;">​</a></h2><ol><li><strong>编辑</strong>：源代码，<code>.c</code>文件</li><li><strong>编译</strong>：<code>.c</code>　--&gt;　<code>.obj</code></li><li><strong>链接</strong>：（<code>.obj</code>＋<code>libxxx.so/a</code>）--&gt; 可执行文件</li><li><strong>运行</strong>：运行可执行文件</li></ol>',17)])])}const u=o(d,[["render",t]]);export{C as __pageData,u as default};
